v.grid(); v.axes();
const q1 = P.q1, q2 = P.q2, r0 = Math.max(0.3, P.r);
const k = 9e9, mu = 1e-6; // charges in microcoulombs
// Charge 1 fixed at origin; charge 2 separation r oscillates so F changes live.
const sep = r0 * (0.7 + 0.3 * Math.sin(t * 1.2)); // looping distance, 0..r0
const x1 = 0, x2 = Math.max(0.4, sep), y0 = 0;
const col = (q) => q > 0 ? H.colors.warn : H.colors.accent;
v.circle(x1, y0, 10, { fill: col(q1), stroke: H.colors.bg, width: 2 });
v.circle(x2, y0, 10, { fill: col(q2), stroke: H.colors.bg, width: 2 });
v.text(q1 > 0 ? "+" : "−", x1 - 0.12, y0 + 0.25, { color: H.colors.ink, size: 16, weight: 700 });
v.text(q2 > 0 ? "+" : "−", x2 - 0.12, y0 + 0.25, { color: H.colors.ink, size: 16, weight: 700 });
// Coulomb force magnitude F = k q1 q2 / r^2  (Newtons), arrow length scales with F
const F = k * Math.abs(q1) * mu * Math.abs(q2) * mu / (sep * sep);
const len = Math.min(3.5, 0.02 * F + 0.4); // bounded visual length in data units
const repel = q1 * q2 > 0;
if (repel) { // forces push the pair apart
  v.arrow(x2, y0, x2 + len, y0, { color: H.colors.good, width: 3 });
  v.arrow(x1, y0, x1 - len, y0, { color: H.colors.good, width: 3 });
} else { // forces pull them together
  v.arrow(x2, y0, x2 - Math.min(len, sep - 0.4), y0, { color: H.colors.good, width: 3 });
  v.arrow(x1, y0, x1 + len, y0, { color: H.colors.good, width: 3 });
}
// distance label
v.line(x1, -1.2, x1, -0.6, { color: H.colors.sub, width: 1 });
v.line(x2, -1.2, x2, -0.6, { color: H.colors.sub, width: 1 });
v.line(x1, -0.9, x2, -0.9, { color: H.colors.sub, width: 1, dash: [4, 4] });
v.text("r = " + sep.toFixed(2) + " m", (x1 + x2) / 2 - 0.8, -1.5, { color: H.colors.sub, size: 12 });
